package com.lightningstudio.watchrss.phone.data.note

/** Fixed Unicode 17 word runs and extended graphemes, shared with watch/mini.
 * At most 80 code points; retreat to a whole grapheme, never split one. */
internal fun deriveNoteTitle(plainText: String, maxWords: Int = 3): String {
    val line = plainText.lineSequence().map { it.trim(::titleWhitespace) }.firstOrNull { it.isNotEmpty() } ?: return ""
    val words = wordRanges(line).take(maxWords).toList()
    if (words.isEmpty()) return truncateNoteTitle(line)
    val start = titleStart(line, words.first().first)
    return truncateNoteTitle(line.substring(start), 80, words.last().last + 1 - start)
}
private fun titleWhitespace(c: Char) = when(c.code) { in 9..13, in 0x2000..0x200a, 0x20,0xa0,0x1680,0x2028,0x2029,0x202f,0x205f,0x3000,0xfeff -> true; else -> false }
private fun wordRanges(line: String): Sequence<IntRange> = sequence {
    var start = -1; var index = 0; var count = 0; var han = true
    while (index <= line.length) {
        val cp = if (index < line.length) line.codePointAt(index) else 0
        val p = titleProperties(cp)
        if (start < 0) { if (p and 1 != 0) { start = index; count = 1; han = p and 4 != 0 } }
        else if (p and 3 != 0 || cp == 0x200c || cp == 0x200d) { count++; han = han && p and 4 != 0 }
        else {
            if (han && count > 4) {
                var from = start; var n = 0
                while (n < count) {
                    val to = line.offsetByCodePoints(from, minOf(2, count - n))
                    yield(from until to); from = to; n += 2
                }
            } else yield(start until index)
            start = -1
        }
        if (index == line.length) break
        index += Character.charCount(cp)
    }
}
private fun gcb(p: Int) = (p ushr 3) and 15
private class ClusterState {
    var seen = false; var previous = 0; var regional = 0
    var indic = false; var linker = false; var pict = false; var zwjPict = false
    fun boundary(next: Int): Boolean {
        val a = gcb(previous); val b = gcb(next)
        if (a == 1 && b == 2) return false
        if (a in 1..3 || b in 1..3) return true
        if (a == 9 && b in listOf(9,10,12,13) || a in listOf(10,12) && b in listOf(10,11) || a in listOf(11,13) && b == 11) return false
        if (b == 4 || b == 5 || b == 8 || a == 7) return false
        if (next and 256 != 0 && indic && linker) return false
        if (next and 128 != 0 && a == 5 && zwjPict) return false
        if (a == 6 && b == 6 && regional % 2 != 0) return false
        return true
    }
    fun accept(next: Int) {
        val b = gcb(next); zwjPict = b == 5 && pict
        if (b != 4) pict = next and 128 != 0
        if (next and 256 != 0) { indic = true; linker = false }
        else if (next and 1536 == 0) { indic = false; linker = false }
        else if (next and 512 != 0) linker = linker || indic
        regional = if (b == 6) regional + 1 else 0; previous = next; seen = true
    }
}
private fun titleStart(text: String, wanted: Int): Int {
    val state = ClusterState(); var index = 0; var start = 0
    while (index < text.length) {
        val cp = text.codePointAt(index); val p = titleProperties(cp)
        if (state.seen && state.boundary(p)) start = index
        if (index >= wanted) return start
        state.accept(p); index += Character.charCount(cp)
    }
    return start
}
internal fun truncateNoteTitle(text: String, limit: Int = 80, wordEnd: Int = text.length): String {
    require(limit >= 0)
    val state = ClusterState(); var index = 0; var last = 0; var count = 0
    while (index < text.length) {
        val cp = text.codePointAt(index); val p = titleProperties(cp)
        if (state.seen && state.boundary(p)) {
            if (index >= wordEnd && count <= limit) return text.substring(0, index)
            last = index
        }
        if (count == limit) return text.substring(0, last)
        state.accept(p); index += Character.charCount(cp); count++
    }
    return text
}
private val titleRanges: IntArray by lazy {
    val bytes = java.util.Base64.getDecoder().decode(TITLE_UNICODE_DATA)
    val out = ArrayList<Int>(); var pos = 0; var cursor = 128
    fun variable(): Int { var v = 0; var shift = 0; var b: Int; do { b = bytes[pos++].toInt() and 255; v = v or ((b and 127) shl shift); shift += 7 } while (b and 128 != 0); return v }
    while (pos < bytes.size) { val start = cursor + variable(); val end = start + variable(); val value = variable(); out.add(start); out.add(end); out.add(value); cursor = end + 1 }
    out.toIntArray()
}
private fun titleProperties(cp: Int): Int {
    if (cp < 128) return if (cp in 48..57 || cp in 65..90 || cp in 97..122) 1 else if (cp == 13) 8 else if (cp == 10) 16 else if (cp < 32 || cp == 127) 24 else 0
    val ranges = titleRanges; var lo = 0; var hi = ranges.size / 3 - 1; var value = 0
    while (lo <= hi) { val mid = (lo + hi) ushr 1; val i = mid * 3; if (cp < ranges[i]) hi = mid - 1 else if (cp > ranges[i+1]) lo = mid + 1 else { value = ranges[i+2]; break } }
    if (cp in 0xac00..0xd7a3) value = (value and 120.inv()) or ((if ((cp-0xac00)%28 == 0) 12 else 13) shl 3)
    return value
}

private const val TITLE_UNICODE_DATA = ""
